// Generated by Kargo: bundles a browser app or an npm library with Rollup. The only argument is the JSON file of options. It
// runs from the directory that holds Rollup's node_modules.
import { builtinModules } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { isAbsolute, relative, resolve, sep } from 'node:path';
import commonjs from '@rollup/plugin-commonjs';
import { nodeResolve } from '@rollup/plugin-node-resolve';
import terser from '@rollup/plugin-terser';
import { rollup } from 'rollup';

const options = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const replacements = options.replace.map((r) => ({ dir: resolve(r.dir), from: r.from, to: r.to }));
const browser = options.platform === 'browser';

// Whether `file` is one of the compiler's modules in `dir`: below it, but not in a package.
const inside = (file, dir) => {
  const rel = relative(dir, file);
  return rel !== '' && !rel.startsWith('..') && !isAbsolute(rel) && !rel.split(sep).includes('node_modules');
};

// Rewrites the names of files the bundler cannot see, such as the `.wasm` file a Kotlin/Wasm module fetches.
const rewrite = {
  name: 'kargo-rewrite',
  transform(code, id) {
    const mine = replacements.filter((r) => inside(resolve(id), r.dir));
    if (mine.length === 0) return null;
    const text = code;
    for (const r of mine) code = code.split(r.from).join(r.to);
    return code === text ? null : { code, map: null };
  },
};

// The compiler's entry module has branches for Node.js and Deno whose imports no page ever takes, and Rollup cannot
// resolve a `node:` module or a URL; only those are left alone, so a package that imports them elsewhere still fails.
const entry = resolve(options.input);
const isUnreachableHostImport = (id, importer) =>
  importer !== undefined &&
  resolve(importer) === entry &&
  (id.startsWith('node:') || id.startsWith('http://') || id.startsWith('https://'));

const isExternal = (id, importer) =>
  isUnreachableHostImport(id, importer) ||
  options.external.some((name) => id === name || id.startsWith(`${name}/`)) ||
  (!browser && (id.startsWith('node:') || builtinModules.includes(id)));

// Minifies each file once it is written in its format; only an ES module can be treated as one.
const minifier = (format) => (options.minify ? [terser({ module: format === 'es' })] : []);

try {
  const bundle = await rollup({
    input: options.input,
    external: isExternal,
    plugins: [rewrite, nodeResolve({ browser, preferBuiltins: !browser }), commonjs()],
    // Rollup treats a package it cannot find as external; a page could not load it, so this is an error.
    onwarn: (warning) => {
      if (warning.code === 'UNRESOLVED_IMPORT') throw new Error(warning.message);
      if (warning.code === 'MISSING_GLOBAL_NAME') {
        throw new Error(`${warning.message} Name it in the \`globals\` of kargo.toml.`);
      }
      console.error(warning.message);
    },
  });
  if (options.library) {
    const { formats, name, globals } = options.library;
    const files = {};
    for (const format of formats) {
      const rollupFormat = { esm: 'es', cjs: 'cjs', umd: 'umd' }[format];
      const extension = { esm: 'mjs', cjs: 'cjs', umd: 'umd.js' }[format];
      const { output } = await bundle.write({
        dir: options.outDir,
        format: rollupFormat,
        name: format === 'umd' ? name : undefined,
        globals: format === 'umd' ? globals : undefined,
        // A UMD file is one file, and a CommonJS or UMD module exports by name.
        inlineDynamicImports: format === 'umd',
        exports: format === 'esm' ? 'auto' : 'named',
        sourcemap: options.sourceMaps,
        entryFileNames: `[name].${extension}`,
        chunkFileNames: `chunk-[hash].${format === 'cjs' ? 'cjs' : 'mjs'}`,
        plugins: minifier(rollupFormat),
      });
      files[format] = output.find((chunk) => chunk.type === 'chunk' && chunk.isEntry).fileName;
    }
    await bundle.close();
    writeFileSync(options.manifest, JSON.stringify({ entry: files.esm ?? Object.values(files)[0], formats: files }));
  } else {
    const { output } = await bundle.write({
      dir: options.outDir,
      format: 'es',
      sourcemap: options.sourceMaps,
      entryFileNames: '[name]-[hash].js',
      chunkFileNames: 'chunk-[hash].js',
      assetFileNames: '[name]-[hash][extname]',
      plugins: minifier('es'),
    });
    await bundle.close();
    const entry = output.find((chunk) => chunk.type === 'chunk' && chunk.isEntry);
    writeFileSync(options.manifest, JSON.stringify({ entry: entry.fileName }));
  }
} catch (error) {
  console.error(error.message ?? String(error));
  process.exit(1);
}
